mapper.select:
SELECT  FROM public.health_examination_batch_participants
WHERE batch_id=#{batchId} AND id IN #{id}
ORDER BY id FOR UPDATE

SELECT EXISTS(SELECT 1 FROM public.health_examination_batch_participants
WHERE batch_id=#{batchId} AND identification_number=#{identity}
AND id <> #{excludeId})

SELECT id,batch_id,batch_participant_id,batch_service_id,is_performed,service_request_id,unit_price_snapshot,recorded_by,recorded_at,created_at,updated_at,row_version
FROM public.health_examination_participant_services WHERE batch_participant_id IN #{id}
ORDER BY id

mapper.sql:
p.batch_id=#{batchId}
AND (LOWER(p.full_name) LIKE #{searchPattern} ESCAPE chr(92) OR LOWER(COALESCE(p.participant_code,'')) LIKE #{searchPattern} ESCAPE chr(92)
OR LOWER(p.department_name) LIKE #{searchPattern} ESCAPE chr(92) OR LOWER(p.position_name) LIKE #{searchPattern} ESCAPE chr(92))
AND p.identification_number=#{identificationNumber}
AND p.batch_day_id=#{batchDayId}
AND p.roster_status=#{rosterStatus}
AND p.attendance_status=#{attendanceStatus}
AND p.service_reconciliation_status=#{reconciliationStatus}

mapper.select:
SELECT p.id,p.batch_id,p.batch_day_id,d.examination_date,p.participant_code,p.full_name,p.date_of_birth,p.sex,p.identification_number, p.department_name,p.position_name,p.roster_status,p.attendance_status,p.service_reconciliation_status AS reconciliation_status, p.actual_examination_date,p.prepared_at,p.row_version FROM public.health_examination_batch_participants p JOIN public.health_examination_batch_days d ON d.batch_id=p.batch_id AND d.id=p.batch_day_id WHERE ORDER BY
p.full_name DESC, p.id DESC p.full_name ASC, p.id ASC p.participant_code DESC NULLS LAST, p.id DESC p.participant_code ASC NULLS LAST, p.id ASC d.examination_date DESC, p.id DESC d.examination_date ASC, p.id ASC p.created_at DESC, p.id DESC p.created_at ASC, p.id ASC p.id DESC p.id ASC
LIMIT #{limit} OFFSET #{offset}
